const event = $json.body ?? $json;
const authorization = $json.headers?.authorization ?? '';
const secret = $env.N8N_WEBHOOK_SECRET ?? '';
if (!secret || authorization !== `Bearer ${secret}`) throw new Error('Unauthorized UtilityOps webhook');
if (event.event !== 'bill.submitted' || event.schema_version !== 1) throw new Error('Unsupported UtilityOps event');
const bill = event.bill;
if (!bill || !Number.isInteger(bill.id) || typeof event.request_id !== 'string' || !event.callback_url) throw new Error('Invalid UtilityOps bill event');
return [{ json: { callbackUrl: event.callback_url, callbackPayload: { bill_id: bill.id, request_id: event.request_id, decision: 'VERIFY', extracted_fields: {}, reason: 'Received and validated by the Phase 3 starter workflow; manual bill review is still required.', recommended_action: 'Review the submitted bill details and attached document.' } } }];
